import{_ as t,o as n,c as o,a2 as a}from"./chunks/framework.CDU0sSpB.js";const u=JSON.parse('{"title":"Contributing","description":"Hearth repository structure, local setup, writing conventions, submission checks, and documentation source of truth.","frontmatter":{"title":"Contributing","description":"Hearth repository structure, local setup, writing conventions, submission checks, and documentation source of truth.","outline":[2]},"headers":[],"relativePath":"en/reference/contributing.md","filePath":"en/reference/contributing.md","lastUpdated":1793881440000}'),s={name:"en/reference/contributing.md"};function i(r,e,d,c,l,h){return n(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="contributing" tabindex="-1">Contributing <a class="header-anchor" href="#contributing" aria-label="Permalink to &quot;Contributing&quot;">​</a></h1><p class="lead">Hearth has entered Phase 1 MVP implementation. The most valuable contributions still clarify boundaries, challenge risk assumptions, add real tasks, and make the documentation easier for implementers to use; implementation changes backed by acceptance evidence are now welcome too. A change does not need to be long, but it must make the conclusion more accurate or the evidence clearer.</p><h2 id="local-setup-and-writing-conventions" tabindex="-1">Local Setup and Writing Conventions <a class="header-anchor" href="#local-setup-and-writing-conventions" aria-label="Permalink to &quot;Local Setup and Writing Conventions&quot;">​</a></h2><p>Formal documentation lives only under <code>docs/</code>, and the site builds directly from it. The README is a repository entry point, not a second copy of the body text. Chinese is the default reading path, and English mirrors use the same paths and structure.</p><table tabindex="0"><thead><tr><th>Directory</th><th>Content</th></tr></thead><tbody><tr><td><code>docs/design/</code></td><td>One overall design and nine parallel module notes</td></tr><tr><td><code>docs/delivery/</code></td><td>Six phases, 24 small stages, and the delivery overview</td></tr><tr><td><code>docs/reference/</code></td><td>Engineering, risk, decisions, boundaries, terminology, checklists, and maintenance</td></tr><tr><td><code>docs/en/</code></td><td>English mirror of every page</td></tr><tr><td><code>docs/.vitepress/</code></td><td>Site configuration, navigation, sidebar, and theme</td></tr><tr><td><code>scripts/</code></td><td>Delivery-page generation and coverage checks</td></tr></tbody></table><p>Local development needs Node.js 20 or newer and npm. Install dependencies with <code>npm ci</code>, develop with <code>npm run docs:dev</code>, build with <code>npm run docs:build</code>, and preview with <code>npm run docs:preview</code>. The build output goes to <code>docs/.vitepress/dist</code> and is not committed.</p><p>State the conclusion first, then the reason. One paragraph should carry one main point. Design pages describe product goals and tradeoffs only, not code paths, internal class names, or implementation detail. Use as few second-level headings as possible and avoid third-level headings that fragment the argument. Prefer tables for comparison and short lists for steps.</p><p>Use shared concepts a user can understand. Explain necessary technical names on first use instead of stacking jargon. Separate facts, judgments, and hypotheses; do not describe plans as delivered capability. Keep Chinese and English at the same path, heading level, and broadly equivalent content. Do not create pages that exist on only one side. When design or delivery conclusions change, check related appendix pages, navigation, sidebar, and cross-links.</p><p>Each development log has one page per day: a summary plus commits, authors, and concrete changes. Append rows when new commits land; do not restore a log index, template, or phase report.</p><h2 id="submission-checks-and-source-of-truth" tabindex="-1">Submission Checks and Source of Truth <a class="header-anchor" href="#submission-checks-and-source-of-truth" aria-label="Permalink to &quot;Submission Checks and Source of Truth&quot;">​</a></h2><p>Complete these checks before submitting:</p><ol><li>Run <code>npm run docs:build</code> and confirm there are no build errors or internal dead links.</li><li>Check that Chinese and English paths correspond and that the sidebar and language switch work.</li><li>Check that design pages contain no code blocks, code paths, or meaningless subheadings.</li><li>If facts, permissions, risks, or phase goals changed, update the related decisions and appendix pages.</li><li>Do not commit build output, caches, local secrets, real user data, or completion claims without evidence.</li></ol><p>The submission message should say what changed, why, which readers or phases are affected, and what evidence is still needed to confirm completion.</p><p><code>docs/</code> is the only formal source shared by the repository and the site. There is no second long-form copy and no separately maintained &quot;archive version&quot;. Change Chinese first and include the English mirror in the same commit. If a translation or link is wrong, fix the source directly.</p><p>The project uses Apache-2.0. Submitting a contribution means agreeing to publish it under that license.</p>',15)])])}const m=t(s,[["render",i]]);export{u as __pageData,m as default};
